solution.code:
#include <stdio.h>

int max_of_three(int a, int b, int c) {
    if (a >= b && a >= c) return a;
    if (b >= c) return b;
    return c;
}

int main() {
    printf("%d\n", max_of_three(50, 20, 10));
    return 0;
}
